import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.DqYch1Cg.js";const s=JSON.parse('{"title":"从一次请求理解 HTTP 版本、报文与协商","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/04http/s_http_7-protocol_practice.md","filePath":"概念与原理/04http/s_http_7-protocol_practice.md","lastUpdated":1794211306000}'),c={name:"概念与原理/04http/s_http_7-protocol_practice.md"};function d(T,t,p,h,i,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="从一次请求理解-http-版本、报文与协商" tabindex="-1">从一次请求理解 HTTP 版本、报文与协商 <a class="header-anchor" href="#从一次请求理解-http-版本、报文与协商" aria-label="Permalink to &quot;从一次请求理解 HTTP 版本、报文与协商&quot;">​</a></h1><h2 id="层次与连接" tabindex="-1">层次与连接 <a class="header-anchor" href="#层次与连接" aria-label="Permalink to &quot;层次与连接&quot;">​</a></h2><p>HTTP 描述请求 / 响应的应用层语义。历史笔记中的“HTTP 三次握手”实际是 TCP 建连；HTTPS 通常还涉及 TLS。HTTP/3 使用 QUIC / UDP，并集成 TLS 1.3 安全握手。不能把所有 HTTP 版本都画成 TCP 三次握手。</p><p>一次访问可能经历 DNS、建连、TLS、发请求和接收响应，但缓存、连接复用、代理和 Service Worker 会改变路径，不能假设每个请求都重新建立连接。URL 的 fragment（<code>#...</code>）不随 HTTP 请求发给服务器，query 则通常会。</p><table tabindex="0"><thead><tr><th>版本</th><th>传输特点</th><th>仍要考虑的边界</th></tr></thead><tbody><tr><td>HTTP/1.1</td><td>持久连接、文本化报文表示</td><td>同连接请求响应组织存在限制；浏览器常使用多连接</td></tr><tr><td>HTTP/2</td><td>二进制帧、多路复用、头部压缩</td><td>TCP 丢包仍可能阻塞同连接上的多个流</td></tr><tr><td>HTTP/3</td><td>QUIC 流与连接管理</td><td>减少跨流传输阻塞，不代表消除拥塞、丢包与业务队列</td></tr></tbody></table><p>HTTP/2 的 server push 不能当成当代浏览器默认优化手段；版本升级也不能替代索引、缓存与资源预算。</p><h2 id="报文与语义" tabindex="-1">报文与语义 <a class="header-anchor" href="#报文与语义" aria-label="Permalink to &quot;报文与语义&quot;">​</a></h2><p>HTTP/1.1 学习报文可按“起始行 → 头部 → 空行 → 可选消息体”理解。HTTP/2、HTTP/3 的线上编码不同，但方法、状态码、字段等语义延续。</p><p>GET 应用于读取，PUT / DELETE 等方法语义具有幂等性，POST 通常没有。幂等不是“返回内容永远相同”，而是重复相同请求对目标资源的预期效果相同。GET 的幂等语义也不保证错误实现的服务端真的无副作用。</p><h2 id="数据协商与重定向" tabindex="-1">数据协商与重定向 <a class="header-anchor" href="#数据协商与重定向" aria-label="Permalink to &quot;数据协商与重定向&quot;">​</a></h2><ul><li><code>Accept</code> 表达期望响应媒体类型；<code>Content-Type</code> 描述当前消息体类型，不能混为一谈。</li><li><code>Accept-Encoding</code> / <code>Content-Encoding</code> 涉及压缩编码，和字符集不是同一个维度。</li><li>响应内容随请求字段变化时，用对应 <code>Vary</code> 保持共享缓存键正确；例如 <code>Vary: Accept-Encoding</code>。</li><li>301 / 302 在历史客户端行为中可能把 POST 改成 GET；303 常用于提交后转向 GET；307 / 308 明确保留方法与请求体。永久跳转的缓存会使回退更复杂。</li></ul><p>CSP 是浏览器安全策略，不属于普通表示格式协商；例如 <code>script-src</code> 控制脚本来源。不存在通用的 <code>content-src</code> 指令，<code>child-src &#39;none&#39;</code> 表示禁止相关加载，不是允许。</p><h2 id="动手核对" tabindex="-1">动手核对 <a class="header-anchor" href="#动手核对" aria-label="Permalink to &quot;动手核对&quot;">​</a></h2><p>在浏览器 Network 中观察请求协议、缓存来源、Timing、响应字段和重定向链；使用已获授权的本地服务比较行为。命令行 <code>curl -I</code> 发送 HEAD，请求语义与完整 GET 不完全一样；排查真实响应时可用 <code>curl -i</code>，避免只看状态码就下结论。</p><p>关联：<a href="./s_http_2-http_status_code">HTTP 状态码</a>、<a href="./s_http_5-https">HTTPS</a>、<a href="./s_http_9-cache_strategy">缓存策略</a>、<a href="/FE-prepare-interview/概念与原理/20deploy/s_deploy_3-nginx">Nginx 代理</a>。</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/HTTP" target="_blank" rel="noreferrer">个人 HTTP 协议与协商笔记</a>；<a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview" target="_blank" rel="noreferrer">MDN HTTP 概述</a>；<a href="https://www.rfc-editor.org/rfc/rfc9110" target="_blank" rel="noreferrer">RFC 9110 HTTP Semantics</a>。</p></blockquote>',16)])])}const _=e(c,[["render",d]]);export{s as __pageData,_ as default};
